                    rootBody->accumulateForceAtBranchCofm(G3D::Vector3(0.0f, upForce, 0.0f));
                    floorPrimitive->getBody()->accumulateForce(G3D::Vector3(0.0f, -upForce, 0.0f), floorTouchInWorld);
                }
            }
        }
