    G3D::Vector3 targetVelocity = floorVelocity + desiredVelocity;
    const Velocity& branchVelocity = rootBody->getBranchVelocity();
    G3D::Vector3 currentAccel = rootBody->getBranchForce() / rootBody->getBranchMass();
